const app=document.querySelector('#app');
const accountNav=document.querySelector('#account-nav');
const toastEl=document.querySelector('#toast');
let session=null,catalog=null,timerId=null,saveId=null,lastApiToken=null,clinicStatus=null;
const CLINIC_DEFAULT='VTHACKS26',CLINIC_STORAGE='vibescore.clinic.participant.v1',CLINIC_DECLINED='vibescore.clinic.declined';
const h=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const jsonHeaders={'content-type':'application/json'};
async function request(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body?jsonHeaders:{}),...(options.headers||{})}});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);return data;}
function clinicState(){try{const value=JSON.parse(localStorage.getItem(CLINIC_STORAGE)||'null');return value&&typeof value.token==='string'&&typeof value.cohortId==='string'?value:null}catch{return null}}
function saveClinicState(value){try{value?localStorage.setItem(CLINIC_STORAGE,JSON.stringify(value)):localStorage.removeItem(CLINIC_STORAGE)}catch{}}
async function clinicEvent(eventType,details={},onceKey=null){const state=clinicState();if(!state||onceKey&&state.events?.[onceKey])return null;let eventId;if(onceKey){const pending=state.pendingEvents?.[onceKey];eventId=typeof pending==='object'&&pending?pending.eventId:typeof pending==='string'?pending:crypto.randomUUID();state.pendingEvents={...(state.pendingEvents||{}),[onceKey]:{eventId,eventType,details}};saveClinicState(state)}try{const result=await request('/api/clinic/events',{method:'POST',body:JSON.stringify({participantToken:state.token,eventType,...(eventId?{eventId}:{}),...details})});if(onceKey){state.events={...(state.events||{}),[onceKey]:true};delete state.pendingEvents[onceKey];saveClinicState(state)}return result}catch(error){toast(`Optional clinic update was not saved: ${error.message}`,true);return null}}
async function flushClinicEvents(){const pending=clinicState()?.pendingEvents||{};for(const [key,event] of Object.entries(pending)){if(event&&typeof event==='object'&&typeof event.eventType==='string')await clinicEvent(event.eventType,event.details||{},key)}}
function toast(message,error=false){toastEl.textContent=message;toastEl.className=`toast show${error?' error':''}`;setTimeout(()=>toastEl.className='toast',3500)}
function navigate(path){history.pushState({},'',path);window.scrollTo({top:0,left:0});render();}
function loading(){app.innerHTML='<div class="route-loading"><span></span><p>Loading…</p></div>'}
function updateNav(){accountNav.innerHTML=session?`<a class="button ghost small" href="/dashboard" data-link>${h(session.user.handle)}</a><button class="button small" data-action="logout">Sign out</button>`:'<a class="button ghost small" href="/login" data-link>Sign in</a><a class="button small" href="/join" data-link>Join beta</a>'}
async function loadSession(){try{session=await request('/api/me')}catch{session=null}updateNav()}
async function getCatalog(){if(!catalog)catalog=(await request('/api/challenges')).challenges;return catalog}
function workflowCard(w){if(!w)return '';const r=w.recommendation||{};return `<section class="card workflow-card"><div class="workflow-score"><div class="eyebrow">Private workflow evidence</div><strong>${h(w.rating)} <small>± ${h(w.rd)}</small></strong><span>${h(w.tier)} · ${h(w.episodes)} episodes · ${h(w.agent)}</span></div><div class="mini-metrics">${metric('Direction',w.subscores.direction)}${metric('Craft',w.subscores.craft)}${metric('Efficiency',w.subscores.efficiency)}${metric('Shipping',w.subscores.shipping)}</div><div class="workflow-next"><span class="status-chip">Current population</span><h3>Strengthen ${h(r.skill||'your workflow')}</h3><p class="muted">This provisional score is recalculated against the current comparison population. Latest report: ${h(new Date(w.generatedAt).toLocaleDateString())}.</p>${r.path?`<a class="button ghost wide" href="${h(r.path)}" data-link>${h(r.title||'Open recommended drill')} →</a>`:''}</div></section>`}
function page(title,body){document.title=`${title} — VibeScore`;document.body.classList.remove('in-workspace');document.querySelector('.site-header').hidden=false;document.querySelector('.site-footer').hidden=false;app.innerHTML=body;if(title==='Dashboard'&&session?.workflow)document.querySelector('.skill-progress')?.insertAdjacentHTML('afterend',workflowCard(session.workflow));app.focus({preventScroll:true})}
function workPage(body){document.title='Challenge — VibeScore';document.body.classList.add('in-workspace');document.querySelector('.site-header').hidden=true;document.querySelector('.site-footer').hidden=true;app.innerHTML=body}
function metric(label,value){return `<div class="metric-line"><span>${h(label)}</span><div class="bar"><i style="--value:${Number(value)}%"></i></div><b>${Number(value)}</b></div>`}
function artifacts(items=[]){return items.length?`<section class="artifact-stack"><h3>Workspace files</h3>${items.map((x,i)=>`<details class="artifact" ${i===0?'open':''}><summary><span>${h(x.name)}</span><small>${h(x.language)}</small></summary><pre><code>${h(x.content)}</code></pre></details>`).join('')}</section>`:''}

function home(){page('Build better with AI',`<div class="shell"><section class="hero"><div class="hero-copy"><div class="eyebrow">The AI builder skill layer</div><h1>Build with AI.<br><span class="gradient-text">Prove you’re good at it.</span></h1><p>VibeScore turns real coding-agent work and controlled challenges into useful coaching, measurable progress, and a profile you can share.</p><div class="hero-actions"><a class="button" href="/join" data-link>Get your VibeScore →</a><a class="button ghost" href="/practice" data-link>Try a skill drill</a></div><div class="trust-row"><span>Raw prompts stay local</span><span>Transparent evidence</span><span>Public by choice</span></div></div><div class="score-preview" aria-label="Example VibeScore profile"><div class="score-orbit"></div><div class="score-card"><div class="score-main"><div class="score-number">1742 <small>± 82</small></div><div class="rank-pill">TOP 12%</div></div><div class="mini-metrics">${metric('Direction',87)}${metric('Craft',76)}${metric('Efficiency',81)}${metric('Shipping',72)}</div></div></div></section><section class="section"><div class="eyebrow">Two paths, one skill profile</div><h2 class="section-title">Measure your work.<br>Sharpen your process.</h2><p class="section-intro">Passive workflow evidence reveals your habits. Controlled practice gives you a fair place to improve and prove them.</p><div class="path-grid"><article class="card path-card"><span class="index">01 · REAL WORK</span><h3>Connect your coding-agent history</h3><p>Run the local MCP on a project you choose. It reduces Claude Code and Codex sessions to private numeric signals, then shows where your workflow helps or hurts.</p><a class="button ghost" href="/privacy" data-link>How private analysis works →</a></article><article class="card path-card"><span class="index">02 · CONTROLLED PRACTICE</span><h3>Train inside an AI-assisted arena</h3><p>Practise framing, context, debugging, verification, review, and efficiency. Take timed coding rounds with an assistant and objective tests.</p><a class="button ghost" href="/practice" data-link>Explore the arena →</a></article></div></section><section class="section"><div class="eyebrow">The loop</div><h2 class="section-title">Evidence that helps you improve.</h2><div class="feature-grid"><article class="card feature-card"><div class="icon-box">01</div><h3>Observe</h3><p>Private local telemetry highlights correction loops, context quality, tool use, verification, and delivery signals.</p></article><article class="card feature-card"><div class="icon-box">02</div><h3>Practise</h3><p>Your weakest dimension maps to focused drills and interview rounds with immediate, honest feedback.</p></article><article class="card feature-card"><div class="icon-box">03</div><h3>Prove</h3><p>Controlled attempts create a separate assessed rating for your profile and the global beta leaderboard.</p></article></div></section></div>`)}

async function practice(){loading();const items=await getCatalog(),params=new URLSearchParams(location.search),filter=['drill','interview'].includes(params.get('kind'))?params.get('kind'):'all',skill=params.get('skill')||'all',skills=[...new Set(items.map(x=>x.skill))];const shown=items.filter(x=>(filter==='all'||x.kind===filter)&&(skill==='all'||x.skill===skill));page('Practice',`<div class="shell"><header class="page-head"><div class="eyebrow">Skill arena</div><h1>Practice the process,<br>not trivia.</h1><p>Short drills strengthen how you direct and review AI. Timed coding rounds test whether you can use assistance and still ship correct work.</p></header><div class="tabs"><button class="tab ${filter==='all'?'active':''}" data-filter="all">All ${items.length}</button><button class="tab ${filter==='drill'?'active':''}" data-filter="drill">Drills ${items.filter(x=>x.kind==='drill').length}</button><button class="tab ${filter==='interview'?'active':''}" data-filter="interview">Interview rounds ${items.filter(x=>x.kind==='interview').length}</button></div><div class="skill-filters"><button class="tab ${skill==='all'?'active':''}" data-skill="all">Every skill</button>${skills.map(x=>`<button class="tab ${skill===x?'active':''}" data-skill="${h(x)}">${h(x)}</button>`).join('')}</div>${shown.length?`<div class="challenge-grid">${shown.map(challengeCard).join('')}</div>`:'<div class="empty">No challenges match these filters.</div>'}</div>`)}
function challengeCard(c){return `<article class="card challenge-card"><div class="challenge-meta"><span class="skill">${h(c.skill)}</span><span>${h(c.difficulty)} · ${c.minutes} min</span></div><h3>${h(c.title)}</h3><p>${h(c.summary)}</p><a class="button ghost wide" href="/challenge/${encodeURIComponent(c.id)}" data-link>${c.kind==='drill'?'Open drill':'View interview'} →</a></article>`}
async function challengeDetail(id){loading();const {challenge:c}=await request(`/api/challenges/${encodeURIComponent(id)}`);page(c.title,`<div class="shell"><div class="challenge-detail"><article class="challenge-body"><div class="eyebrow">${h(c.kind)} · ${h(c.skill)}</div><h1>${h(c.title)}</h1><p>${h(c.summary)}</p><h2>Your brief</h2><p>${h(c.prompt)}</p><h2>What good work includes</h2><ul class="requirements">${c.requirements.map(x=>`<li>${h(x)}</li>`).join('')}</ul>${artifacts(c.artifacts)}</article><aside class="card side-panel"><dl><div><dt>Difficulty</dt><dd>${h(c.difficulty)}</dd></div><div><dt>Time</dt><dd>${c.minutes} min</dd></div><div><dt>Skill</dt><dd>${h(c.skill)}</dd></div><div><dt>Format</dt><dd>${h(c.artifacts?.length?'Workspace round':c.kind)}</dd></div></dl><button class="button wide" data-start="${h(c.id)}" data-mode="practice">Start practice</button>${c.kind==='interview'?`<button class="button ghost wide" style="margin-top:.6rem" data-start="${h(c.id)}" data-mode="rated">Start rated round</button>`:''}<p class="form-note">${c.kind==='interview'?'Rated interview timers begin immediately. Your first completed rated attempt on a task is eligible for the beta rating.':'Structured feedback is coaching evidence and does not affect the controlled challenge rating.'}</p></aside></div></div>`)}

function authPage(kind){const join=kind==='join',recover=kind==='recover';page(join?'Join the beta':recover?'Recover access':'Sign in',`<div class="auth-wrap"><div class="card auth-card"><div class="eyebrow">${join?'Create your profile':recover?'Account recovery':'Welcome back'}</div><h1>${join?'Start building better.':recover?'Use your recovery code.':'Sign in to VibeScore.'}</h1><p>${join?'Your profile stays private until you publish it.':recover?'Successful recovery replaces your old sessions and code.':'Continue your drills, attempts, and progress.'}</p><form class="form" id="auth-form" data-kind="${kind}"><div class="field"><label for="handle">Handle</label><input id="handle" name="handle" required minlength="2" maxlength="24" pattern="[a-z0-9][a-z0-9_-]+" autocomplete="username" placeholder="hokie_builder"></div>${recover?'<div class="field"><label for="recovery">Recovery code</label><input id="recovery" name="recoveryCode" required autocomplete="off"></div>':''}<div class="field"><label for="password">${recover?'New password':'Password'}</label><input id="password" name="${recover?'newPassword':'password'}" type="password" required minlength="10" autocomplete="${join?'new-password':'current-password'}"></div><button class="button wide" type="submit">${join?'Create account':recover?'Recover account':'Sign in'} →</button><p class="form-note">${join?'Already have an account? <a href="/login" data-link>Sign in</a>':recover?'Remembered it? <a href="/login" data-link>Sign in</a>':'Lost access? <a href="/recover" data-link>Use your recovery code</a>'}</p></form></div></div>`)}
function showRecovery(code){page('Save recovery code',`<div class="auth-wrap"><div class="card auth-card"><div class="eyebrow">One important step</div><h1>Save this code.</h1><p>It is the only way to recover your account. We store only a one-way hash and cannot show it again.</p><div class="recovery-box"><code>${h(code)}</code></div><button class="button wide" style="margin-top:1rem" data-action="copy-recovery" data-code="${h(code)}">Copy recovery code</button><a class="button ghost wide" style="margin-top:.6rem" href="/dashboard" data-link>I saved it — continue</a></div></div>`)}
function showApiToken(token){lastApiToken=token;const config=`VIBESCORE_SERVER=${location.origin}\nVIBESCORE_TOKEN=${token}`;page('Connect your coding agent',`<div class="auth-wrap token-wrap"><div class="card auth-card"><div class="eyebrow">Local MCP connection</div><h1>Save this token.</h1><p>This credential is shown once. It lets your local VibeScore MCP publish privacy-safe aggregate evidence to your account; it cannot reveal your password or access browser account controls.</p><div class="recovery-box"><code>${h(token)}</code></div><button class="button wide" style="margin-top:1rem" data-action="copy-api-token">Copy token</button><h2>Collector environment</h2><p class="muted">Add these variables to the MCP process, then run <code>npm run mcp</code> from the VibeScore repository.</p><pre class="config-block">${h(config)}</pre><button class="button ghost wide" data-action="copy-mcp-config">Copy environment block</button><a class="button ghost wide" style="margin-top:.6rem" href="/settings" data-link>I saved it — return to settings</a></div></div>`)}

async function dashboard(){if(!session)return navigate('/login');loading();const [me,items]=await Promise.all([request('/api/me'),getCatalog()]);session=me;updateNav();const s=session.summary,a=session.attempts,byId=new Map(items.map(x=>[x.id,x])),skills=['framing','context','debugging','verification','review','efficiency'];const progress=skills.map(skill=>{const done=a.filter(x=>x.status==='submitted'&&byId.get(x.challengeId)?.skill===skill),scores=done.map(x=>Number(x.result?.totalScore??x.result?.score)).filter(Number.isFinite);return {skill,count:done.length,score:scores.length?Math.round(scores.reduce((n,x)=>n+x,0)/scores.length):null}});const next=progress.slice().sort((x,y)=>x.count-y.count||(x.score??0)-(y.score??0))[0];page('Dashboard',`<div class="shell"><header class="page-head"><div class="eyebrow">Your command center</div><h1>Welcome back,<br>${h(session.user.handle)}.</h1><p>Keep the loop moving: practise a weak skill, finish a controlled round, then compare the result with your real workflow.</p></header><div class="stats-grid"><div class="card stat-card"><strong>${s.rating??'—'}</strong><span>Challenge rating</span></div><div class="card stat-card"><strong>${s.ratedTasks}</strong><span>Rated tasks</span></div><div class="card stat-card"><strong>${s.completed}</strong><span>Completed attempts</span></div><div class="card stat-card"><strong>${session.user.isPublic?'Live':'Private'}</strong><span>Profile visibility</span></div></div><section class="card skill-progress"><div class="challenge-meta"><span>Skill progress</span><span>Practice and rated attempts</span></div><div class="skill-grid">${progress.map(x=>`<a href="/practice?skill=${encodeURIComponent(x.skill)}" data-link><span>${h(x.skill)}</span><b>${x.score===null?'Start':`${x.score}%`}</b><small>${x.count} completed</small></a>`).join('')}</div></section><div class="dashboard-grid"><section class="card"><div class="challenge-meta"><span>Recent activity</span><a href="/practice" data-link>Find a challenge →</a></div><div class="activity">${a.length?a.slice(0,8).map(x=>`<a class="activity-row" href="/attempt/${h(x.id)}" data-link><span><b>${h(byId.get(x.challengeId)?.title||x.challengeId.replaceAll('-',' '))}</b><br><small class="muted">${new Date(x.startedAt).toLocaleDateString()} · ${h(x.mode)}</small></span><span class="status-chip ${h(x.status)}">${h(x.status)}</span></a>`).join(''):'<div class="empty">No attempts yet. Your first drill takes about seven minutes.</div>'}</div></section><aside class="card"><div class="eyebrow">Next move</div><h2>${s.ratedTasks<2?'Establish your beta rating':`Strengthen ${h(next.skill)}`}</h2><p class="muted">${s.ratedTasks<2?'Complete two different rated interview tasks to appear on the public challenge leaderboard.':`Your ${h(next.skill)} evidence is currently the thinnest. Complete one focused drill, then compare the feedback.`}</p><a class="button wide" href="${s.ratedTasks<2?'/practice?kind=interview':`/practice?skill=${encodeURIComponent(next.skill)}`}" data-link>${s.ratedTasks<2?'Choose an interview':'Open recommended drills'}</a><a class="button ghost wide" style="margin-top:.6rem" href="/connect" data-link>Connect project evidence</a></aside></div></div>`)}

async function attemptPage(id){if(!session)return navigate('/login');loading();const [data,status]=await Promise.all([request(`/api/attempts/${encodeURIComponent(id)}`),request('/api/status')]),a=data.attempt,c=data.challenge;if(a.status==='submitted')return resultPage(a,c);if(c.kind==='drill')return drillAttempt(a,c);return interviewAttempt(a,c,data.messages||[],status.ai)}
function timer(deadline){clearInterval(timerId);const el=document.querySelector('#timer');if(!el)return;const update=()=>{const seconds=Math.max(0,Math.floor((Date.parse(deadline)-Date.now())/1000)),minutes=Math.floor(seconds/60);el.textContent=`${String(minutes).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;el.setAttribute('aria-label',seconds?`${minutes} minutes ${seconds%60} seconds remaining`:'Time expired');if(!seconds)clearInterval(timerId)};update();timerId=setInterval(update,1000)}
function drillAttempt(a,c){workPage(`<div class="workspace"><div class="work-top"><a href="/challenge/${h(c.id)}" data-link>← Exit</a><h1>${h(c.title)}</h1><span class="status-chip">${h(a.mode)}</span><span class="timer" id="timer" role="timer" aria-live="off" aria-atomic="true"></span></div><div class="drill-workspace"><div class="eyebrow">${h(c.skill)} ${c.artifacts?.length?'scenario':'drill'}</div><h2>${h(c.prompt)}</h2><ul class="requirements">${c.requirements.map(x=>`<li>${h(x)}</li>`).join('')}</ul>${artifacts(c.artifacts)}<form id="drill-form" data-clinic-skill="${h(c.skill)}"><div class="field"><label for="answer">${h(c.responseLabel||'Your instruction to the AI')}</label><textarea class="drill-answer" id="answer" name="answer" placeholder="Be specific about evidence, constraints, and success checks…">${h(a.answer)}</textarea></div><div class="hero-actions"><button class="button" type="submit">Check my response →</button><button class="button ghost" type="button" data-action="save-draft">Save draft</button></div></form></div></div>`);timer(a.deadline)}
function interviewAttempt(a,c,messages,ai){const provider=ai?.enabled?`${String(ai.provider).replace(/^./,x=>x.toUpperCase())} interview coach`:'AI coach unavailable';workPage(`<div class="workspace"><div class="work-top"><a href="/challenge/${h(c.id)}" data-link>← Exit</a><h1>${h(c.title)}</h1><span class="status-chip">${h(a.mode)}</span><span class="timer" id="timer" role="timer" aria-live="off" aria-atomic="true"></span></div><div class="work-grid"><section class="work-pane prompt-pane"><div class="pane-head">Brief + workspace</div><div class="content"><div class="eyebrow">${h(c.skill)}</div><h2>${h(c.prompt)}</h2><ul class="requirements">${c.requirements.map(x=>`<li>${h(x)}</li>`).join('')}</ul>${artifacts(c.artifacts)}${c.examples?.length?`<h3>Examples</h3>${c.examples.map(x=>`<div class="card"><code>${h(JSON.stringify(x.input))} → ${h(JSON.stringify(x.output))}</code><p>${h(x.explanation)}</p></div>`).join('')}`:''}<div id="run-results" class="results"></div></div></section><section class="work-pane solution-pane"><div class="pane-head">Solution · JavaScript</div><textarea id="code-editor" class="code-editor" spellcheck="false" aria-label="Code editor">${h(a.code||c.starterCode)}</textarea><div class="reflection-panel"><label for="reflection">Verification reflection <span>Autosaves while you type</span></label><p>What did you ask the assistant, and how did you verify the result?</p><textarea id="reflection" maxlength="8000" placeholder="Example: I clarified the stopping rule, tested the zero-retry boundary, then reviewed the hidden assumptions…">${h(a.reflection||'')}</textarea></div><div class="editor-actions"><button class="button ghost small" data-action="run-code">Run tests</button><button class="button small" data-action="submit-code" data-clinic-skill="${h(c.skill)}" data-clinic-rated="${a.mode==='rated'}">Submit solution</button></div></section><aside class="work-pane assistant-pane"><div class="pane-head" id="coach-provider">${h(provider)}</div><div class="chat" id="chat">${messages.length?messages.map(m=>`<div class="message ${h(m.role)}">${h(m.content)}</div>`).join(''):`<div class="message assistant">${ai?.enabled?'I can help you clarify the task, reason through tradeoffs, debug, and verify. I won’t hand you a complete solution.':'The coach is not configured right now. You can still write code, run tests, and submit the round.'}</div>`}</div><form class="chat-form" id="chat-form"><textarea name="message" aria-label="Message the interview coach" placeholder="Ask for a hint…" ${ai?.enabled?'':'disabled'}></textarea><button class="button small" type="submit" ${ai?.enabled?'':'disabled'}>Send</button></form></aside></div></div>`);timer(a.deadline);const editor=document.querySelector('#code-editor'),reflection=document.querySelector('#reflection'),autosave=()=>{clearTimeout(saveId);saveId=setTimeout(()=>saveAttempt(a.id,{code:editor.value,reflection:reflection.value},false),1200)};editor.addEventListener('input',autosave);reflection.addEventListener('input',autosave)}
async function saveAttempt(id,payload,notify=true){await request(`/api/attempts/${id}`,{method:'PATCH',body:JSON.stringify(payload)});if(notify)toast('Draft saved')}
function resultPage(a,c){const r=a.result||{},score=r.totalScore??r.score??0;page('Attempt result',`<div class="shell"><section class="card result-hero"><div class="eyebrow" style="justify-content:center">Attempt complete</div><div class="result-score">${h(score)}${r.totalScore!==undefined||r.maxScore===100?'<small>%</small>':''}</div><h1>${h(c.title)}</h1><p class="muted">${h(r.notice||'Your result has been saved.')}</p>${r.ratingNote?`<p class="rating-note">${h(r.ratingNote)}</p>`:''}<div class="hero-actions" style="justify-content:center"><a class="button" href="/practice" data-link>Keep practising</a><a class="button ghost" href="/dashboard" data-link>View dashboard</a></div></section>${r.criteria?`<section class="section"><h2 class="section-title">Rubric feedback</h2><div class="feature-grid">${r.criteria.map(x=>`<article class="card"><div class="challenge-meta"><span>${h(x.label)}</span><b>${x.pointsEarned}/${x.pointsPossible}</b></div><p class="muted">${h(x.feedback)}</p></article>`).join('')}</div></section>`:''}${r.visibleTests?`<section class="section"><h2 class="section-title">Test evidence</h2><div class="card">${r.visibleTests.map(x=>`<div class="test-row"><span>${h(x.label)}</span><b class="${x.passed?'pass':'fail'}">${x.passed?'Passed':'Failed'}</b></div>`).join('')}<p class="muted">Hidden tests passed: ${r.hiddenTestsPassed}/${r.hiddenTestsTotal}</p></div></section>`:''}</div>`)}

async function leaderboard(type='challenge'){loading();const data=await request(`/api/leaderboard?type=${type}`);page('Leaderboard',`<div class="shell"><header class="page-head"><div class="eyebrow">Public beta ladder</div><h1>Skill earns the rank.</h1><p>Challenge ratings use controlled first attempts. Imported workflow scores remain separate and provisional.</p></header><div class="tabs"><button class="tab ${type==='challenge'?'active':''}" data-board="challenge">Challenge rating</button><button class="tab ${type==='workflow'?'active':''}" data-board="workflow">Workflow score</button></div><div class="card leaderboard"><div class="leader-row head"><span>Rank</span><span>Builder</span><span>Score</span><span>Evidence</span></div>${data.entries.length?data.entries.map((x,i)=>`<a class="leader-row" href="/profile/${encodeURIComponent(x.handle)}" data-link><span class="rank">#${i+1}</span><span class="leader-name">${h(x.handle)}</span><span class="leader-score">${h(x.rating??'—')}</span><span class="muted">${type==='challenge'?`${x.ratedTasks} tasks`:`${x.episodes} episodes`}</span></a>`).join(''):'<div class="empty">The public beta ladder is ready for its first eligible builders.</div>'}</div></div>`)}
async function profile(handle){loading();const {profile:p}=await request(`/api/profile/${encodeURIComponent(handle)}`);const rating=p.challenge.rating??p.workflow?.rating??'—';page(`${p.handle}'s profile`, `<div class="shell"><section class="profile-hero"><div class="page-head"><div class="eyebrow">Public builder profile</div><h1>@${h(p.handle)}</h1><p>Two evidence lanes tell the honest story: controlled challenge results and provisional real-work signals.</p></div><div class="profile-rating"><div><strong>${h(rating)}</strong><span>${p.challenge.rating?'Challenge rating':'Workflow score'}</span></div></div></section><div class="path-grid"><article class="card"><div class="challenge-meta"><span>Assessed challenges</span><span>${p.challenge.eligible?'Ranked':'Building evidence'}</span></div><h2>${p.challenge.rating??'Not established'}</h2><p>${p.challenge.ratedTasks} rated tasks · ${p.challenge.completed} completed attempts</p></article><article class="card"><div class="challenge-meta"><span>Imported workflow</span><span>Provisional</span></div><h2>${p.workflow?.rating??'Not connected'}</h2><p>${p.workflow?`${p.workflow.episodes} episodes · ${h(p.workflow.agent)}`:'No public local-work report yet.'}</p></article></div></div>`)}

async function settings(){if(!session)return navigate('/login');session=await request('/api/me');page('Settings',`<div class="shell"><header class="page-head"><div class="eyebrow">Account controls</div><h1>Settings.</h1><p>Your data stays private until you choose otherwise. Deleting your account removes its attempts, messages, reports, and scores.</p></header><div class="dashboard-grid"><section class="card"><h2>Public profile</h2><p class="muted">${session.user.isPublic?'Your profile and eligible scores are visible on the public leaderboard.':'Your account, attempts, and reports are private.'}</p><button class="button ${session.user.isPublic?'ghost':''}" data-action="visibility" data-value="${!session.user.isPublic}">${session.user.isPublic?'Make profile private':'Publish my profile'}</button><a class="button ghost wide" style="margin-top:.7rem" href="/connect" data-link>Connect Codex + Claude</a></section><section class="card"><h2>Delete account</h2><p class="muted">This permanently removes your beta data.</p><form id="delete-form" class="form"><div class="field"><label>Type ${h(session.user.handle)} to confirm</label><input name="confirmHandle" autocomplete="off"></div><button class="button danger" type="submit">Delete my account</button></form></section></div></div>`)}

async function connectWork(){if(!session)return navigate('/login');loading();const data=await request('/api/workflow'),o=data.bundle?.overall;page('Connect your AI work',`<div class="shell"><header class="page-head"><div class="eyebrow">Private local evidence</div><h1>Connect Codex<br>and Claude Code.</h1><p>The VibeScore MCP finds project-matched sessions only when you ask, reduces them locally, previews the exact numeric upload, and requires confirmation before publishing.</p></header>${data.connected?`<section class="card workflow-score"><div><div class="eyebrow">Latest provisional score</div><h2>${h(data.latest?.rating??'Calculated')}</h2><p>${h(data.bundle.agent)} · ${o.episodes} episodes · generated ${h(new Date(data.bundle.generatedAt).toLocaleString())}</p></div><div class="mini-metrics">${metric('Context',Math.round(o.firstPromptContextScore*100))}${metric('Verify',Math.round(o.verifyAfterEditRatio*100))}${metric('Recovery',Math.round(o.errorRecoveryRate*100))}${metric('Agentic',Math.round(o.agenticLeverage*100))}</div></section>`:'<div class="empty">No workflow report is connected yet. Complete the local setup below, then ask your coding agent to run the VibeScore workflow.</div>'}<div class="connect-grid"><section class="card"><div class="index">01 · INSTALL</div><h2>Run the local MCP</h2><p class="muted">Clone this repository, install dependencies, and use the absolute path to <code>collector/src/mcp.ts</code> in your MCP client.</p><pre><code>git clone https://github.com/aaditya0602/VibeScore.git
cd VibeScore
npm install</code></pre></section><section class="card"><div class="index">02 · AUTHORIZE</div><h2>Create a connection token</h2><p class="muted">The token can publish aggregate workflow evidence to your account. It is shown once and replacing it revokes the previous token.</p><button class="button" data-action="generate-api-token">Generate connection token</button></section></div><section id="connection-secret" class="section connection-secret"></section><section class="card"><div class="index">03 · RUN</div><h2>Ask your coding agent</h2><ol class="requirements"><li>Find project sessions for this repository.</li><li>Analyze the Codex and Claude Code sessions you select.</li><li>Explain the report and recommend drills.</li><li>Preview the publish payload and show its SHA-256.</li><li>Publish only after you approve that exact preview.</li></ol><p class="form-note">Workflow scores are provisional usage evidence. They remain separate from controlled interview ratings.</p></section></div>`)}

function showConnectionToken(token){const origin=location.origin,path='C:\\ABSOLUTE_PATH\\VibeScore\\collector\\src\\mcp.ts';const codex=`[mcp_servers.vibescore]\ncommand = "node"\nargs = ["${path.replaceAll('\\','\\\\')}"]\nenv = { VIBESCORE_SERVER = "${origin}", VIBESCORE_TOKEN = "${token}" }`;const claude=JSON.stringify({mcpServers:{vibescore:{command:'node',args:[path],env:{VIBESCORE_SERVER:origin,VIBESCORE_TOKEN:token}}}},null,2);document.querySelector('#connection-secret').innerHTML=`<div class="eyebrow">Shown once</div><h2>Save your MCP configuration now.</h2><p class="muted">Replace the example Windows path with the absolute path on your computer. Keep this token private.</p><div class="config-grid"><article class="card"><div class="challenge-meta"><span>Codex config.toml</span><button class="button ghost small" data-copy-target="codex-config">Copy</button></div><pre id="codex-config"><code>${h(codex)}</code></pre></article><article class="card"><div class="challenge-meta"><span>Claude Code .mcp.json</span><button class="button ghost small" data-copy-target="claude-config">Copy</button></div><pre id="claude-config"><code>${h(claude)}</code></pre></article></div>`;document.querySelector('#connection-secret').scrollIntoView({behavior:'smooth'})}
function privacy(){page('Privacy',`<div class="shell"><header class="page-head"><div class="eyebrow">Local first by design</div><h1>Your code is yours.</h1></header><article class="privacy-copy"><h2>What stays on your machine</h2><p>The VibeScore MCP analyzes only project and session files you explicitly select. Prompt text, source code, commands, file paths, and filenames are reduced locally and are not included in publishable reports.</p><h2>How the career navigator uses a goal</h2><p>A navigator goal is processed on the VibeScore server and reduced to a career keyword for the Databricks resource search. When Gemini is configured, the goal and matched resources may be sent to Gemini to compose the guidance. The goal is not stored in clinic analytics or added to a public profile.</p><h2>What you can publish</h2><p>Publishing is opt-in. The MCP first shows the exact numeric bundle and its SHA-256 digest. Upload requires a second call with that exact digest and explicit confirmation.</p><h2>What the server stores</h2><p>Accounts, challenge attempts, assistant messages, numeric reports, score history, and feedback. Credentials are stored as one-way hashes. Profiles are private by default.</p><h2>What the scores mean</h2><p>Imported workflow scores are provisional self-reported evidence. Controlled challenge ratings come from server-run tests, but are not identity-proctored hiring credentials. We keep them separate.</p><h2>Your controls</h2><p>You can make your profile private or delete the account and its associated beta data from Settings.</p></article></div>`)}
function clinicControls(){const state=clinicState(),declined=sessionStorage.getItem(CLINIC_DECLINED)==='1';if(state){const expires=state.retentionUntil?new Date(state.retentionUntil).toLocaleDateString():'within 90 days',events=state.events||{};return `<div class="clinic-active"><div><span class="status-chip submitted">Opted in</span><h3>Anonymous clinic evaluation is active.</h3><p>Clinic ${h(state.cohortId)} · automatically deleted ${h(expires)}. The participant token stays in this browser; the server stores only its hash.</p></div><div class="clinic-response-grid">${events.followup?'<div class="clinic-thanks">Follow-up band submitted.</div>':`<form id="clinic-followup-form" class="clinic-mini-form"><label for="followup-band">Optional follow-up skill band</label><select id="followup-band" name="outcomeBand"><option value="starting">Starting</option><option value="developing">Developing</option><option value="ready">Ready</option></select><button class="button ghost small" type="submit">Save follow-up</button></form>`}${events.feedback?'<div class="clinic-thanks">Usefulness rating submitted.</div>':`<form id="clinic-feedback-form" class="clinic-mini-form"><label for="usefulness-rating">Optional usefulness rating</label><select id="usefulness-rating" name="usefulnessRating"><option value="5">5 · Very useful</option><option value="4">4 · Useful</option><option value="3">3 · Neutral</option><option value="2">2 · Limited</option><option value="1">1 · Not useful</option></select><button class="button ghost small" type="submit">Save rating</button></form>`}</div><button class="text-button danger-text" data-action="clinic-delete">Delete my clinic data</button></div>`}if(declined)return `<div class="clinic-declined"><strong>You declined analytics.</strong><p>Nothing is collected, and the complete readiness and navigator experience remains available.</p><button class="button ghost small" data-action="clinic-reconsider">Change my choice</button></div>`;return `<form id="clinic-consent-form" class="clinic-consent-form"><div class="field"><label for="clinic-code">Clinic code</label><input id="clinic-code" name="cohortId" value="${CLINIC_DEFAULT}" minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9_-]+" required></div><div class="clinic-consent-copy"><strong>Share anonymous outcomes only if you choose.</strong><p>We collect the clinic code, a rotating pseudonym, coarse skill and readiness bands, completion events, and an optional 1–5 usefulness rating. We do not collect your name, email, profile handle, prompts, code, ANS searches, or free-form answers. Data expires after ${h(clinicStatus?.retentionDays??90)} days and you can delete it here sooner.</p></div><div class="clinic-consent-actions"><button class="button small" type="button" data-action="clinic-opt-in" ${clinicStatus?.enabled?'':'disabled'}>Share anonymous outcomes</button><button class="button ghost small" type="button" data-action="clinic-decline">No thanks</button></div>${clinicStatus?.enabled?'':'<p class="form-note">Evaluation opt-in is not configured yet. Every learning feature still works.</p>'}</form>`}
function impactCard(summary,label){if(summary.suppressed)return `<article class="impact-card suppressed"><div class="challenge-meta"><span>${label}</span><span>${summary.synthetic?'Synthetic demo':'Live pilot'}</span></div><strong>${h(summary.participantCountLabel)}</strong><h3>Protected small cohort</h3><p>Metrics, counts, skill gaps, and freshness stay hidden until ${h(summary.minimumCohort)} participants contribute.</p></article>`;const m=summary.metrics||{},gap=summary.skillGaps?.[0],percent=value=>value===null||value===undefined?'—':`${Math.round(value*100)}%`;return `<article class="impact-card"><div class="challenge-meta"><span>${label}</span><span>${summary.synthetic?'Synthetic demo':'Live pilot'}</span></div><div class="impact-metrics"><div><strong>${h(summary.participantCount)}</strong><span>Participants</span></div><div><strong>${percent(m.readinessCompletionRate)}</strong><span>Readiness · ${h(m.readinessCompletions)}/${h(m.readinessStarts)}</span></div><div><strong>${percent(m.positiveFeedbackRate)}</strong><span>Useful · ${h(m.positiveFeedbackResponses)}/${h(m.feedbackResponses)}</span></div><div><strong>${gap?h(gap.skill):'—'}</strong><span>Largest gap${gap?` · ${h(gap.participants)} people`:''}</span></div></div><p>Last event ${summary.freshness?h(new Date(summary.freshness).toLocaleString()):'unavailable'}. Observed outcomes do not establish causation.</p></article>`}
function renderImpact(data){const box=document.querySelector('#impact-summary');if(!box)return;box.innerHTML=`<div class="impact-grid">${impactCard(data.live,'Current cohort')}${impactCard(data.synthetic,'Demo comparison')}</div><p class="navigator-disclaimer">Denominators and response counts are shown with every available rate. Live and synthetic data are never combined.</p>`}
async function refreshImpact(cohortId=clinicState()?.cohortId||CLINIC_DEFAULT){try{renderImpact(await request(`/api/impact/summary?cohort=${encodeURIComponent(cohortId)}`))}catch(error){const box=document.querySelector('#impact-summary');if(box)box.innerHTML=`<div class="empty compact">${h(error.message)}</div>`}}
async function hokie(){const cohortId=clinicState()?.cohortId||CLINIC_DEFAULT,[status,impact]=await Promise.all([request('/api/status'),request(`/api/impact/summary?cohort=${encodeURIComponent(cohortId)}`)]);clinicStatus=status.clinic;page('VibeScore for Hokies',`<div class="shell"><header class="page-head hokie-head"><div class="eyebrow">HokieAI Career Navigator</div><h1>Turn AI skill into<br>your next move.</h1><p>Choose the skill you want to strengthen and tell us where you are headed. VibeScore pairs a focused drill with governed Virginia Tech and career resources when the live campus data connection is available.</p><div class="free-callout">Free to use. The readiness check and career navigator require no account and no public profile.</div><div class="trust-row"><span>No account required</span><span>Facts and AI guidance labeled</span><span>Practice always available</span></div></header><section class="card clinic-panel"><div class="clinic-panel-head"><div><div class="eyebrow">Ut Prosim clinic</div><h2>Help improve the workshop—optionally.</h2></div><a href="/docs/clinic-facilitator-guide.md" target="_blank" rel="noopener">Facilitator guide ↗</a></div><div id="clinic-controls" role="status" aria-live="polite">${clinicControls()}</div></section><section class="navigator-layout"><div class="navigator-intro"><div class="eyebrow">Career pathfinder</div><h2>Make a plan grounded in evidence.</h2><p>Databricks supplies approved campus resources. Gemini can explain why they fit. VibeScore chooses the practice step that builds the underlying skill.</p><div class="source-state ${status.databricks?.enabled?'live':'offline'}"><i></i><span>${status.databricks?.enabled?'Databricks campus catalog configured':'Campus catalog not configured'}</span></div></div><form class="card navigator-form" id="navigator-form"><div class="field"><label for="navigator-goal">What are you preparing for?</label><textarea id="navigator-goal" name="goal" minlength="10" maxlength="500" required placeholder="Prepare for an AI-assisted software engineering interview and build a portfolio I can explain clearly."></textarea></div><div class="field"><label for="navigator-skill">Skill to strengthen</label><select id="navigator-skill" name="skill"><option value="framing">Framing the right problem</option><option value="context">Choosing useful context</option><option value="debugging">Debugging with evidence</option><option value="verification" selected>Verifying AI output</option><option value="review">Reviewing risky changes</option><option value="efficiency">Working efficiently</option></select></div><button class="button coral wide" type="submit">Build my career path →</button><p class="form-note">Your goal is processed on the VibeScore server, reduced to a career keyword for Databricks search, and may be sent with matched resources to configured Gemini to compose guidance. It is not stored in clinic analytics or added to your public profile.</p></form></section><div id="navigator-results" class="navigator-results" role="status" aria-live="polite" tabindex="-1"><div class="empty compact">Your recommended drill and sourced campus resources will appear here.</div></div><section class="section"><div class="eyebrow">Two-minute readiness check</div><h2 class="section-title">What kind of AI builder are you?</h2><section class="card hokie-banner" id="hokie-quiz" role="region" aria-live="polite" tabindex="-1"><div class="challenge-meta"><span>Question 1 of 3</span><span>Career readiness check</span></div><h2>When your coding assistant produces a plausible solution, what do you do next?</h2><div class="quiz-options"><button class="quiz-option" data-quiz="0" data-points="0">Ship it while the context is fresh</button><button class="quiz-option" data-quiz="0" data-points="1">Read the main path and fix anything obvious</button><button class="quiz-option" data-quiz="0" data-points="2">Run focused tests, inspect edge cases, and review the diff</button></div></section></section><section class="section impact-section"><div class="eyebrow">Organizer impact view</div><h2 class="section-title">Evidence with privacy thresholds.</h2><p class="section-intro">Cohorts under ten remain suppressed. Live pilot outcomes and synthetic demonstration data stay visibly separate.</p><div id="impact-summary" aria-live="polite"> </div></section><section class="section ans-section"><div class="eyebrow">GoDaddy ANS trust explorer</div><h2 class="section-title">Find the agents behind the name.</h2><p class="section-intro">Search the Agent Name Service directory, inspect one registered identity, and see which trust signals exist before choosing a service.</p><form class="ans-search" id="ans-search"><input name="query" aria-label="Search registered AI agents" minlength="2" maxlength="128" placeholder="Try career, campus, or MCP" required><button class="button" type="submit">Discover agents</button></form><div id="ans-results" class="ans-results" role="status" aria-live="polite" tabindex="-1"><div class="empty">ANS discovery becomes available when the production GoDaddy credentials are installed on the server.</div></div></section></div>`);renderImpact(impact);void flushClinicEvents()}

function renderNavigator(data){const box=document.querySelector('#navigator-results'),stamp=data.dataSource.retrievedAt?new Date(data.dataSource.retrievedAt).toLocaleString():null,newest=data.dataSource.freshness?.newestLastVerifiedAt?new Date(data.dataSource.freshness.newestLastVerifiedAt).toLocaleDateString():null;box.innerHTML=`<section class="card navigator-plan"><div class="navigator-plan-copy"><div class="challenge-meta"><span>${h(data.skillGap)} skill path</span><span>${data.guidance.generatedBy==='gemini'?`Gemini guidance · ${h(data.guidance.model||'configured model')}`:'VibeScore guidance'}</span></div><h2>${h(data.recommendedDrill.title)}</h2><p>${h(data.guidance.text)}</p><a class="button" href="${h(data.recommendedDrill.path)}" data-link data-clinic-drill="${h(data.skillGap)}">Start the recommended drill →</a></div><aside><span class="source-label">Practice evidence</span><strong>${h(data.skillGap)}</strong><small>One controlled exercise, saved to your profile when signed in.</small></aside></section><div class="resource-heading"><div><div class="eyebrow">Retrieved facts</div><h2>Campus and career resources</h2></div>${stamp?`<p>Queried ${h(stamp)}${newest?`<br>Newest verification ${h(newest)}`:''}</p>`:''}</div>${data.careerResources.length?`<div class="resource-grid">${data.careerResources.map(resource=>`<article class="card resource-card"><div class="challenge-meta"><span>${h(resource.source)}</span><span>${resource.lastVerifiedAt?`Verified ${h(new Date(resource.lastVerifiedAt).toLocaleDateString())}`:'Verification date unavailable'}</span></div><h3>${h(resource.name)}</h3><p>${h(resource.description)}</p><div class="resource-tags">${[...resource.audience,...resource.careerTags].slice(0,5).map(tag=>`<span>${h(tag)}</span>`).join('')}</div><a href="${h(resource.url)}" target="_blank" rel="noopener noreferrer">Open official resource ↗</a></article>`).join('')}</div>`:`<div class="card resource-unavailable"><div><strong>${data.dataSource.enabled?'Live campus resources could not be reached':'Campus resources are not connected yet'}</strong><p>${h(data.dataSource.message||'The focused VibeScore practice path remains available while the Databricks catalog is offline.')}</p></div><a class="button ghost" href="${h(data.recommendedDrill.path)}" data-link data-clinic-drill="${h(data.skillGap)}">Continue with practice</a></div>`}<p class="navigator-disclaimer">${h(data.disclaimer)}</p>`;box.focus({preventScroll:true})}

function renderAnsAgents(data){const box=document.querySelector('#ans-results'),stamp=data.retrievedAt?new Date(data.retrievedAt).toLocaleString():'Unavailable';box.innerHTML=`<div class="registry-meta"><span>${h(data.environment||'unknown')} registry</span><span>Retrieved ${h(stamp)}</span><span>${data.totalItems===null?'Result count unavailable':`${h(data.totalItems)} registered agents`}</span></div>${data.agents.length?`<div class="ans-grid">${data.agents.map(a=>`<article class="card ans-card"><div class="challenge-meta"><span>${h(a.protocol||'Agent')}</span><span>${h(a.status)}</span></div><h3>${h(a.displayName)}</h3><p>${h(a.description||'Registered agent')}</p><div class="trust-row"><span>${a.trustScore===null?'Trust pending':`Trust ${h(a.trustScore)}`}</span><span>${h(a.ansName||a.host||'Registry identity')}</span></div><button class="button ghost small" data-ans-id="${h(a.agentId)}">Inspect registry signals →</button></article>`).join('')}</div>`:'<div class="empty">No registered agents matched that search.</div>'}`;box.focus({preventScroll:true})}
function renderAnsTrust(data){const box=document.querySelector('#ans-results'),stamp=data.retrievedAt?new Date(data.retrievedAt).toLocaleString():'Unavailable';box.insertAdjacentHTML('afterbegin',`<article class="card ans-trust"><div><div class="eyebrow">ANS registry identity</div><h3>${h(data.displayName)}</h3><p>${h(data.ansName||data.host||data.agentId)}</p></div><div class="profile-rating"><div><strong>${data.trustScore===null?'—':h(data.trustScore)}</strong><span>Registry trust score</span></div></div><dl><div><dt>Lifecycle</dt><dd>${h(data.status)}</dd></div><div><dt>Signal coverage</dt><dd>${data.coverageRatio===null?'Not published':`${Math.round(data.coverageRatio*100)}%`}</dd></div><div><dt>Identity</dt><dd>${data.trustVector.identity??'—'}</dd></div><div><dt>Integrity</dt><dd>${data.trustVector.integrity??'—'}</dd></div></dl><p class="muted">Retrieved from the ${h(data.environment)} ANS registry at ${h(stamp)}. Missing signals: ${h(data.missingSignals.join(', ')||'none reported')}. Registry identity and scores are not a guarantee of safety, quality, or endorsement.</p></article>`);box.focus({preventScroll:true})}
const quiz=[{q:'When a coding agent fails twice on the same issue, what is your next move?',a:[['Ask it to try again',0],['Switch models immediately',1],['Stop, summarize evidence, and change the hypothesis',2]]},{q:'What makes a strong first prompt?',a:[['A detailed list of technologies',1],['The user outcome, constraints, evidence, and success checks',2],['A short command so the model has freedom',0]]}];
async function quizStep(index,points){const box=document.querySelector('#hokie-quiz');if(index>=quiz.length){const type=points>=5?'The Systems Builder':points>=3?'The Fast Iteration Builder':'The Instinctive Builder',skill=points>=5?'efficiency':points>=3?'verification':'framing',outcomeBand=points>=5?'ready':points>=3?'developing':'starting';await clinicEvent('readiness_completed',{skill,outcomeBand},'readinessCompleted');box.innerHTML=`<div class="eyebrow">Your builder archetype</div><h2>${type}</h2><p>You have useful instincts. Your recommended starting focus is <b>${skill}</b>—one controlled drill will make the next step concrete.</p><div class="hero-actions"><a class="button coral" href="/practice?skill=${encodeURIComponent(skill)}" data-link data-clinic-drill="${h(skill)}">Start my recommended practice →</a><button class="button ghost" data-action="use-hokie-skill" data-skill="${h(skill)}">Use this in my career plan</button><a class="button ghost" href="/join" data-link>Save a public profile</a></div>`;const focus=document.querySelector('#navigator-skill');if(focus)focus.value=skill;box.focus({preventScroll:true});return}const item=quiz[index];box.innerHTML=`<div class="challenge-meta"><span>Question ${index+2} of 3</span><span>Career readiness check</span></div><h2>${h(item.q)}</h2><div class="quiz-options">${item.a.map(([label,p])=>`<button class="quiz-option" data-quiz="${index+1}" data-total="${points+Number(p)}">${h(label)}</button>`).join('')}</div>`;box.focus({preventScroll:true})}
function notFound(){page('Not found','<div class="error-page"><h1>404</h1><p class="muted">That page moved, or never existed.</p><a class="button" href="/" data-link>Back home</a></div>')}

async function render(){clearInterval(timerId);const path=location.pathname;try{if(path==='/')return home();if(path==='/practice')return practice();if(path==='/login'||path==='/join'||path==='/recover')return authPage(path.slice(1));if(path==='/dashboard')return dashboard();if(path==='/connect')return connectWork();if(path==='/leaderboard')return leaderboard();if(path==='/settings')return settings();if(path==='/privacy')return privacy();if(path==='/hokie')return hokie();if(path.startsWith('/challenge/'))return challengeDetail(decodeURIComponent(path.slice(11)));if(path.startsWith('/attempt/'))return attemptPage(decodeURIComponent(path.slice(9)));if(path.startsWith('/profile/'))return profile(decodeURIComponent(path.slice(9)));return notFound()}catch(error){page('Something went wrong',`<div class="error-page"><h1>We hit a snag.</h1><p class="muted">${h(error.message)}</p><button class="button" data-action="retry">Try again</button></div>`)}finally{document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===path))}}

document.addEventListener('click',async event=>{const link=event.target.closest('[data-link]');if(link&&link.origin===location.origin){event.preventDefault();if(link.dataset.clinicDrill)await clinicEvent('drill_started',{skill:link.dataset.clinicDrill},`drillStarted-${link.dataset.clinicDrill}`);navigate(link.getAttribute('href'));return}const target=event.target.closest('button');if(!target)return;try{
  if(target.dataset.filter){const params=new URLSearchParams(location.search);target.dataset.filter==='all'?params.delete('kind'):params.set('kind',target.dataset.filter);navigate(`/practice${params.size?`?${params}`:''}`);return}
  if(target.dataset.skill){const params=new URLSearchParams(location.search);target.dataset.skill==='all'?params.delete('skill'):params.set('skill',target.dataset.skill);navigate(`/practice${params.size?`?${params}`:''}`);return}
  if(target.dataset.board)return leaderboard(target.dataset.board);
  if(target.dataset.start){if(!session)return navigate('/login');target.disabled=true;const data=await request(`/api/challenges/${encodeURIComponent(target.dataset.start)}/start`,{method:'POST',body:JSON.stringify({mode:target.dataset.mode})});navigate(`/attempt/${data.attempt.id}`)}
  if(target.dataset.action==='logout'){await request('/api/logout',{method:'POST'});session=null;updateNav();navigate('/')}
  if(target.dataset.action==='copy-recovery'){await navigator.clipboard.writeText(target.dataset.code);toast('Recovery code copied')}
  if(target.dataset.action==='create-api-token'){target.disabled=true;const data=await request('/api/me/api-token',{method:'POST'});showApiToken(data.token)}
  if(target.dataset.action==='revoke-api-token'){if(!confirm('Revoke the current collector token? Any connected local MCP will stop publishing until you create a replacement.'))return;target.disabled=true;await request('/api/me/api-token',{method:'DELETE'});toast('Collector token revoked');settings()}
  if(target.dataset.action==='copy-api-token'){if(!lastApiToken)throw new Error('This token is no longer available. Create a replacement.');await navigator.clipboard.writeText(lastApiToken);toast('API token copied')}
  if(target.dataset.action==='copy-mcp-config'){if(!lastApiToken)throw new Error('This token is no longer available. Create a replacement.');await navigator.clipboard.writeText(`VIBESCORE_SERVER=${location.origin}\nVIBESCORE_TOKEN=${lastApiToken}`);toast('MCP environment copied')}
  if(target.dataset.action==='retry')render();
  if(target.dataset.action==='save-draft'){const id=location.pathname.slice(9);await saveAttempt(id,{answer:document.querySelector('#answer')?.value,code:document.querySelector('#code-editor')?.value,reflection:document.querySelector('#reflection')?.value})}
  if(target.dataset.action==='run-code'){target.disabled=true;const id=location.pathname.slice(9),data=await request(`/api/attempts/${id}/run`,{method:'POST',body:JSON.stringify({code:document.querySelector('#code-editor').value})});document.querySelector('#run-results').innerHTML=`<h3>Visible tests</h3>${data.results.map(x=>`<div class="test-row"><span>${h(x.id)}</span><b class="${x.passed?'pass':'fail'}">${x.passed?'Passed':'Failed'}</b></div>`).join('')}`;target.disabled=false}
  if(target.dataset.action==='submit-code'){if(!confirm('Submit this solution? A rated first attempt cannot be repeated for rating credit.'))return;target.disabled=true;const id=location.pathname.slice(9),data=await request(`/api/attempts/${id}/submit`,{method:'POST',body:JSON.stringify({code:document.querySelector('#code-editor').value,reflection:document.querySelector('#reflection')?.value||''})});if(target.dataset.clinicRated==='true')await clinicEvent('rated_task_submitted',{skill:target.dataset.clinicSkill},`ratedTask-${id}`);toast(`Submitted: ${data.result.totalScore}%`);render()}
  if(target.dataset.action==='visibility'){const data=await request('/api/me',{method:'PATCH',body:JSON.stringify({isPublic:target.dataset.value==='true'})});session.user=data.user;toast(data.user.isPublic?'Profile published':'Profile is private');settings()}
  if(target.dataset.action==='generate-api-token'){target.disabled=true;const data=await request('/api/me/api-token',{method:'POST'});showConnectionToken(data.token);target.remove()}
  if(target.dataset.copyTarget){const value=document.querySelector(`#${target.dataset.copyTarget}`)?.textContent||'';await navigator.clipboard.writeText(value);toast('Configuration copied')}
  if(target.dataset.action==='clinic-opt-in'){const form=document.querySelector('#clinic-consent-form');if(!form?.reportValidity())return;target.disabled=true;const cohortId=String(new FormData(form).get('cohortId')||'').trim().toUpperCase(),data=await request('/api/clinic/consent',{method:'POST',body:JSON.stringify({cohortId,consent:true})});saveClinicState({token:data.participantToken,cohortId,retentionUntil:data.retentionUntil,events:{}});sessionStorage.removeItem(CLINIC_DECLINED);await clinicEvent('readiness_started',{},'readinessStarted');document.querySelector('#clinic-controls').innerHTML=clinicControls();toast('Anonymous clinic outcomes are enabled');await refreshImpact(cohortId)}
  if(target.dataset.action==='clinic-decline'){const form=document.querySelector('#clinic-consent-form'),cohortId=String(form?new FormData(form).get('cohortId')||CLINIC_DEFAULT:CLINIC_DEFAULT).trim().toUpperCase();await request('/api/clinic/consent',{method:'POST',body:JSON.stringify({cohortId,consent:false})});sessionStorage.setItem(CLINIC_DECLINED,'1');saveClinicState(null);document.querySelector('#clinic-controls').innerHTML=clinicControls();toast('Analytics declined. Nothing will be collected.')}
  if(target.dataset.action==='clinic-reconsider'){sessionStorage.removeItem(CLINIC_DECLINED);document.querySelector('#clinic-controls').innerHTML=clinicControls()}
  if(target.dataset.action==='clinic-delete'){if(!confirm('Delete your anonymous clinic events now? This cannot be undone.'))return;const state=clinicState();if(!state)return;target.disabled=true;await request('/api/clinic/participant',{method:'DELETE',body:JSON.stringify({participantToken:state.token})});saveClinicState(null);sessionStorage.setItem(CLINIC_DECLINED,'1');document.querySelector('#clinic-controls').innerHTML=clinicControls();await refreshImpact(state.cohortId);toast('Your clinic data was deleted')}
  if(target.dataset.ansId){target.disabled=true;const data=await request(`/api/ans/agents/${encodeURIComponent(target.dataset.ansId)}`);renderAnsTrust(data);target.disabled=false}
  if(target.dataset.action==='use-hokie-skill'){const focus=document.querySelector('#navigator-skill');if(focus)focus.value=target.dataset.skill;document.querySelector('#navigator-form')?.scrollIntoView({behavior:'smooth',block:'center'})}
  if(target.dataset.quiz!==undefined){target.disabled=true;await quizStep(Number(target.dataset.quiz),Number(target.dataset.total??target.dataset.points??0))}
}catch(error){target.disabled=false;toast(error.message,true)}});

document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;try{
  if(form.id==='auth-form'){const values=Object.fromEntries(new FormData(form));const kind=form.dataset.kind,path=kind==='join'?'/api/register':kind==='recover'?'/api/recover':'/api/login';const data=await request(path,{method:'POST',body:JSON.stringify(values)});await loadSession();if(data.recoveryCode)return showRecovery(data.recoveryCode);navigate('/dashboard')}
  if(form.id==='drill-form'){const id=location.pathname.slice(9),answer=form.answer.value;await saveAttempt(id,{answer},false);await request(`/api/attempts/${id}/submit`,{method:'POST',body:JSON.stringify({answer})});await clinicEvent('drill_completed',{skill:form.dataset.clinicSkill},`drillCompleted-${id}`);render()}
  if(form.id==='chat-form'){const input=form.message,message=input.value.trim();if(!message)return;input.value='';const chat=document.querySelector('#chat');chat.insertAdjacentHTML('beforeend',`<div class="message user">${h(message)}</div>`);const id=location.pathname.slice(9),data=await request(`/api/attempts/${id}/chat`,{method:'POST',body:JSON.stringify({message})});document.querySelector('#coach-provider').textContent=`${String(data.provider).replace(/^./,x=>x.toUpperCase())} interview coach · ${data.model}`;chat.insertAdjacentHTML('beforeend',`<div class="message assistant">${h(data.message)}</div>`);chat.scrollTop=chat.scrollHeight}
  if(form.id==='navigator-form'){const button=form.querySelector('button[type="submit"]'),box=document.querySelector('#navigator-results');button.disabled=true;box.innerHTML='<div class="route-loading navigator-loading"><span></span><p>Matching your goal to practice and campus resources…</p></div>';try{const values=Object.fromEntries(new FormData(form));renderNavigator(await request('/api/navigator/recommend',{method:'POST',body:JSON.stringify(values)}));box.scrollIntoView({behavior:'smooth',block:'start'})}catch(error){box.innerHTML=`<div class="empty compact">${h(error.message)} Your practice library is still available.</div>`;box.focus({preventScroll:true});throw error}finally{button.disabled=false}}
  if(form.id==='ans-search'){const query=form.query.value.trim(),box=document.querySelector('#ans-results');box.innerHTML='<div class="route-loading"><span></span><p>Searching the ANS registry…</p></div>';renderAnsAgents(await request(`/api/ans/search?q=${encodeURIComponent(query)}`))}
  if(form.id==='clinic-followup-form'){const outcomeBand=String(new FormData(form).get('outcomeBand')),saved=await clinicEvent('followup_completed',{outcomeBand},'followup');if(saved){document.querySelector('#clinic-controls').innerHTML=clinicControls();toast('Follow-up saved');await refreshImpact()}}
  if(form.id==='clinic-feedback-form'){const usefulnessRating=Number(new FormData(form).get('usefulnessRating')),saved=await clinicEvent('feedback_submitted',{usefulnessRating},'feedback');if(saved){document.querySelector('#clinic-controls').innerHTML=clinicControls();toast('Usefulness rating saved');await refreshImpact()}}
  if(form.id==='delete-form'){const confirmHandle=form.confirmHandle.value;if(!confirm('Permanently delete this account and all beta data?'))return;await request('/api/me',{method:'DELETE',body:JSON.stringify({confirmHandle})});session=null;updateNav();navigate('/')}
}catch(error){toast(error.message,true)}});
window.addEventListener('popstate',render);
await loadSession();render();
